# Euler-Mascheroni constant for BST average path length calculation
EULER_MASCHERONI: float = 0.5772156649015328606065120900824024310421


def _c_factor(n: int) -> float:
    """Average path length of unsuccessful search in a Binary Search Tree (BST)."""
    if n <= 1:
        return 0.0
    if n == 2:
        return 1.0
    return float(2.0 * (np.log(n - 1) + EULER_MASCHERONI) - 2.0 * (n - 1) / n)


C_MAX_SAMPLES: float = _c_factor(MAX_SAMPLES)

